    Bug 1972272 - Fix memory leak in nsImapHostSessionList::SetNamespaceFromPrefForHost. r=edicharry


    CID: 1639730

    Seems what is detected is potential leak of prefixes[i] for between i = len and numNamespaces.

    Differential Revision: https://phabricator.services.mozilla.com/D253782

diff --git a/mailnews/imap/src/nsImapHostSessionList.cpp b/mailnews/imap/src/nsImapHostSessionList.cpp
index d0c5cae26c5..4b8bc1a3f6b 100644
--- a/mailnews/imap/src/nsImapHostSessionList.cpp
+++ b/mailnews/imap/src/nsImapHostSessionList.cpp
@@ -355,7 +355,9 @@ NS_IMETHODIMP nsImapHostSessionList::SetNamespaceFromPrefForHost(
           nsImapNamespace* ns =
               new nsImapNamespace(nstype, thisns, delimiter, true);
           if (ns) host->fNamespaceList->AddNewNamespace(ns);
-          PR_FREEIF(thisns);
+        }
+        for (int i = 0; i < numNamespaces; i++) {
+          PR_FREEIF(prefixes[i]);
         }
         PR_Free(prefixes);
       }
